foreach (['en', 'fr', 'es', 'it', 'zh'] as $lang) {
    $path = __DIR__ . "/../resources/lang/{$lang}.json";
    $json = json_decode(file_get_contents($path), true, 512, JSON_THROW_ON_ERROR);

    unset($json['DIGITEXIA ? INFRASTRUCTURE CONSOLE']);

    foreach ($fr as $key => $frValue) {
        $json[$key] = $lang === 'fr' ? $frValue : $key;
    }

    ksort($json, SORT_NATURAL | SORT_FLAG_CASE);
    file_put_contents($path, json_encode($json, JSON_PRETTY_PRINT | JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES) . PHP_EOL);
    echo "{$lang} updated\n";
}

